# Generated by tools/packgen/banking/make_packs.py from snippets/trading/swap_reprice.py there. Edit that source, not this file.
# title: Swap legs repriced off the curves
# description: Every unsettled cash flow of the trade's LEGS: fixed flows at their booked RATE, floating flows not fixed yet re-projected as simple forwards off the leg's DISCOUNT_INDEX curve plus FLOAT_SPREAD (single-curve; a flow already fixing keeps its booked RATE), signed by LEG_ECONOMIC_TYPE (Pay or Receive) and discounted on the same curve (ACT/365F); each leg's PV, the net against the risk engine's MTM (trade-valuation TVAL-<TRADE_ID>), and a cash-flow ladder by year.
# kinds: trade

from datetime import date
import pandas as pd
from drishti import quant as q

doc = view.doc
num = lambda x: float(x) if x not in (None, "") else None          # noqa: E731 - an extract writes numbers as text, or blank
as_of = date.fromisoformat(view.business_date or "2026-09-30")
yrs = lambda d: (date.fromisoformat(d) - as_of).days / 365.0         # noqa: E731
curves = {}
flows = []
for leg in doc.get("LEGS") or []:
    cid = leg.get("DISCOUNT_INDEX") or f"CRV-{leg.get('CURRENCY') or doc['CURRENCY']}-OIS"
    if cid not in curves:
        curves[cid] = q.ZeroCurve.from_points((await drishti.get_async("ir-curve", cid))["POINTS"])
    crv, sign = curves[cid], (-1 if leg.get("LEG_ECONOMIC_TYPE") == "Pay" else 1)
    for cf in leg.get("CASH_FLOWS") or []:
        if not cf.get("PAYMENT_DATE") or yrs(cf["PAYMENT_DATE"]) <= 0 or not cf.get("START_DATE"):
            continue
        t0, t1, n = yrs(cf["START_DATE"]), yrs(cf["END_DATE"] or cf["PAYMENT_DATE"]), num(cf.get("NOTIONAL")) or 0.0
        rate, src = num(cf.get("RATE")), "booked"
        if leg.get("LEG_TYPE") == "FLOAT" and t0 > 0:
            rate, src = crv.forward(t0, t1) + (num(cf.get("FLOAT_SPREAD")) or 0.0), "projected"
        amount = sign * n if cf.get("FLOW_TYPE") == "Principal" else sign * n * (rate or 0.0) * max(t1 - t0, 0)
        tp = yrs(cf["PAYMENT_DATE"])
        flows.append({"LEG_ID": leg["LEG_ID"], "LEG_TYPE": leg.get("LEG_TYPE"), "PAYMENT_DATE": cf["PAYMENT_DATE"], "RATE": rate,
                      "rate from": src, "amount": amount, "df": crv.df(tp), "pv": amount * crv.df(tp), "curve": cid})
if not flows:
    raise ValueError(f"{view.id} ({doc.get('PRODUCT_TYPE')}) has no unsettled interest flows: this snippet is for swaps")
cf = pd.DataFrame(flows)
by_leg = cf.groupby(["LEG_ID", "LEG_TYPE", "curve"]).agg(flows=("pv", "size"), pv=("pv", "sum")).reset_index()
show(by_leg, title=f"{view.id} ({doc['SOURCE_SYSTEM']} {doc['PRODUCT_TYPE']}): legs repriced")
try:
    val = await drishti.get_async("trade-valuation", f"TVAL-{doc['TRADE_ID']}")
    print(f"Net PV repriced {cf['pv'].sum():,.0f} against the risk engine's MTM {val['MTM']:,.0f} {val.get('MTM_CURRENCY', '')}")
except Exception as e:                                                # market-risk not installed, or no valuation for the trade
    print(f"Net PV repriced {cf['pv'].sum():,.0f} (no valuation to compare: {e})")
show(cf, title="Unsettled cash flows")
cf["year"] = cf["PAYMENT_DATE"].str[:4]
ladder = cf.pivot_table(index="year", columns="LEG_TYPE", values="amount", aggfunc="sum", fill_value=0)
chart(ladder, kind="bar", title="Cash flows by year (undiscounted)")
